#include<bits/stdc++.h>

using namespace std;

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  cin >> n;
  string s;
  cin >> s;
  int cur=0,res=0;
  for(auto &nx : s){
    if(nx=='R'){cur++;}
    else{cur=0;}
    res=max(res,cur);
  }
  cout << res << "\n";
  return 0;
}
